DROP TABLE IF EXISTS vc_fund;
CREATE TABLE vc_fund (mgr TEXT, fund TEXT, size TEXT, usd_m REAL, whenx TEXT, status TEXT, lp TEXT, note TEXT, url TEXT, conf TEXT);
DROP TABLE IF EXISTS lp_side;
CREATE TABLE lp_side (lp TEXT, what TEXT, url TEXT);
DROP TABLE IF EXISTS lp_commit;
CREATE TABLE lp_commit (lp TEXT, fund TEXT, total_m INTEGER, commit_m INTEGER, year INTEGER, url TEXT);
DROP TABLE IF EXISTS lp_fund;
CREATE TABLE lp_fund (lp TEXT, mgr TEXT, fund TEXT, vintage INTEGER, committed_usd INTEGER, asof TEXT, url TEXT);
CREATE INDEX i_vc_u ON vc_fund(usd_m);
