INSERT INTO vc_fund VALUES ('Andreessen Horowitz','複数ファンド(成長・アプリ・インフラ・American Dynamism・バイオなど)','150億ドル超','15000.0','2026年1月','組成完了','2026年のファンドのLP名簿は非公開。CalPERSが2023年に、a16zの新ファンド「California Innovation Opportunities」へ4億ドルをコミット(Fortuneが公的記録から報道。a16zが大手のカリフォルニア州年金を迎えた初の例)。ミシガン大学基金なども、過去のファンドのLPと報じられています(Forbes・PitchBook)。サウジのPIF傘下のSanabilも、a16zを投資先に挙げています。','a16z自身の公式投稿(2026年1月9日)で、150億ドル超と内訳を確認。成長67.5億ドル、アプリ17億、インフラ17億、American Dynamism 11.76億、バイオ・ヘルス7億など。運用資産は900億ドル超。','https://a16z.com/why-did-we-raise-15b/','高');
INSERT INTO vc_fund VALUES ('Sequoia Capital','新ファンド群(拡張戦略など)','約100億ドル','10000.0','2026年11月','組成完了','2026年の新ファンドのLPは非公開。過去のファンドでは、カリフォルニア大学基金(UC Investments)が2018年以降20本のLP(公的記録の開示請求)、ミシガン大学基金が2015年組成のSequoia U.S. Venture Fund XVのLPとされています。','同社が2026年11月4日にXに投稿したメモに「~$10Bn in new funds」とあり、これが新しい資金の唯一の公表数字(SECのForm Dはファンド名のみで、規模の記載なし、と報道)。メモの本文は取得できず、報道経由。2026年4月には約70億ドルの拡張戦略ファンドが報じられた(関係者への取材ベース)。11月の社内メモで、合計約100億ドルとされた。内訳は未公表。','https://techcrunch.com/2026/11/04/sequoia-hits-rewind-undoing-20-years-of-expansion/','中');
INSERT INTO vc_fund VALUES ('Thrive Capital','Thrive X','100億ドル超','10000.0','2026年2月','組成完了','CalPERS(Thrive X Growth 3.86億ドル、Thrive X Opportunity 5億ドル。2026年。CalPERS公式のPE一覧、2026年3月31日時点)。ほかは非公開。','ジョシュ・クシュナー氏本人のXの投稿(2026年2月17日)で、「100億ドル超(Exceeding $10 billion)」「初期10億ドル、成長90億ドル」と確認(同社サイトの文面は未確認)。LPへの感謝の言及のみで、名前は非公開。前回のThrive IX(2024年、約50億ドル)の約2倍。 SECのForm D(私募の届出)で、Thrive Capital Partners X(Growth、Opportunity Fund、Growth-A、Growth-B)が、2025年10月〜2026年4月に提出されていることを確認(金額は、書類を取得できず未確認)。','https://x.com/JoshuaKushner/status/2023732796649271619','高');
INSERT INTO vc_fund VALUES ('General Catalyst','新ファンド群','約100億ドル(目標)','10000.0','2026年3月(協議中)','協議中','CalPERSは、前回(2024年)のGeneral Catalyst XIIの4本(Creation 2億、Endurance 2.935億、Health Assurance 1億、Ignition 2億ドル)に出資(CalPERS公式のPE一覧)。今回の新ファンドのLPは未確定。','Bloombergが、約100億ドルの調達を投資家と協議中と報道。確定の報道は、確認できていません。前回は2024年10月に80億ドル。 SECのForm Dで、General Catalyst Group XIII(本体とFeeder)が2026年3月24日に提出されていることを確認(募集は始まっている。金額・クローズは未確認)。','https://www.bloomberg.com/news/articles/2026-03-10/general-catalyst-discusses-raising-about-10-billion-in-funding-push','中');
INSERT INTO vc_fund VALUES ('Lightspeed Venture Partners','XV-A・XV-B・Select VI・Opportunity III など','90億ドル超(複数ファンド)','9000.0','2025年12月','組成完了','CalPERS(Opportunity III 2.25億ドル、Select VI 1.25億ドル、XV-A 4,950万ドル、XV-B 6,050万ドル。2025年。CalPERS公式のPE一覧、2026年3月31日時点)。ほかは非公開。','2025年12月15日の同社発表(Business Wire)で、6本合計90億ドル超。XV-A 9.8億ドル、XV-B 12億ドル、Select VI 18億ドル、Opportunity III 33億ドル、Co-Investment I 6億ドル。ほかに単一投資家向けの媒体で12.5億ドル。','https://www.businesswire.com/news/home/20251215319417/en','高');
INSERT INTO vc_fund VALUES ('Founders Fund','Growth IV','60億ドル','6000.0','2026年5月','組成完了','今回のGrowth IV: 外部LPが45億ドル(ソブリン・ウェルス・ファンドを含むと報道、名前は非公開)。残り15億ドルは、ピーター・ティールさんと同社の幹部・従業員。過去のファンド(PitchBook、第三者のデータベース): Founders Fund IIはゴードン&ベティ・ムーア財団、Lexington Partners、スタンフォード大学基金。Founders Fund IIIはデューク大学の退職年金など。','同社の成長ファンドとして4本目。前のファンドから1年足らずで組成。 SECのForm D(原文を確認)で、販売済み6,024,585,000ドル(GPの出資約束を含む)、投資家370、初回販売2026年3月6日。外部45億/内部15億ドルの内訳は報道のみで、公的資料では未確認。','https://www.bloomberg.com/news/articles/2026-05-01/thiel-s-founders-fund-raises-6-billion-in-its-largest-ever-haul','高');
INSERT INTO vc_fund VALUES ('Bessemer Venture Partners','新ファンド群(初期・成長)','57.5億ドル','5750.0','2026年9月','組成完了','CalPERS(Bessemer Venture Partners XII Institutional 1.15億ドル。2024年。CalPERS公式のPE一覧、2026年3月31日時点)。SJCERAがXIIIへ3,000万ドル、Century Fund IIIへ2,000万ドルを2026年6月に可決(同機関の議事資料、Muse調査・原典未確認)。ほかは非公開。','2026年9月23日の同社発表で、57.5億ドル(初期17.5億・成長40億、単一クローズ)を確認。ファンド名は発表に記載なし。初期(シード〜)17.5億ドル、成長40億ドル。ファンド名は非公表。米国・欧州・インド・イスラエルに投資。運用資産は約200億ドル。 SECのForm Dで、Bessemer Venture Partners XIII(本体・Institutional・Parallelなど5本)が2026年9月14日に提出されていることを確認。ファンド名は「XIII」(金額は未確認)。','https://www.bvp.com/news/5-75-billion-to-back-the-founders-building-what-s-next','高');
INSERT INTO vc_fund VALUES ('Khosla Ventures','新ファンド群(シード・初期・Opportunity)','最大55億ドル(目標)','5500.0','2026年7月(協議中)','協議中','未確定','Bloombergが、最大55億ドルを協議中と報道。シード約10億、初期約20億、Opportunity約25億ドルが目標と報じられたが、確定していません。','https://www.bloomberg.com/news/articles/2026-07-23/khosla-ventures-in-talks-to-raise-5-5-billion-in-new-funds','中');
INSERT INTO vc_fund VALUES ('Kleiner Perkins','KP22(初期)・KP Select IV(成長)','35億ドル','3500.0','2026年3月','組成完了','非公開','同社の公式投稿(2026年3月24日)で、KP22(初期)10億ドルと、成長ファンド25億ドルを確認。成長ファンドの名称「KP Select IV」は、第三者の報道による。約2年前の20億ドルから75%増。','https://www.kleinerperkins.com/perspectives/our-new-funds-kp22-select-iv-flex/','高');
