INSERT INTO vc_fund VALUES ('Coral Capital','Coral Capital 4号ファンド','250億円',NULL,'2024年5月','組成完了','機関投資家が約7割(日本政策投資銀行(DBJ)、第一生命保険、みずほ銀行など。Bloomberg報道)。海外LPは約3割(比率のみ公表)。','同社の公式記事で、4号「Coral Capital IV」の250億円組成完了を確認(PR TIMES 2024年5月23日にも発表)。当初予定の200億円を、3カ月で上回った。運用総額は約600億円。3号(2021年、140億円)には、米Founders Fundも出資と報道(ダイヤモンド)。','https://www.coralcap.co/2024/12/coral-capital-year-in-review/','高');
