INSERT INTO vc_fund VALUES ('三菱UFJ銀行・三菱UFJ信託銀行(MUFG)','ミッドレイター期のスタートアップ向けエクイティ・ファンド(アルテミス・ベンチャーズ)','500億円規模(目標)',NULL,'2025年10月に設立を発表。クローズは2026年度の予定','設立・募集中','MUFG(設立元)。ほかは、国内外の投資家からLP出資を募集中。','ミッドレイター期(成長段階)のスタートアップに投資。','https://www.tr.mufg.jp/ippan/release/pdf_mutb/251001_2.pdf','高');
INSERT INTO vc_fund VALUES ('Felicis','Felicis Fund X','9億ドル','900.0','2025年6月10日','組成完了','非公開(LPは「組織の種類」のみ公表)','同社最大のファンド。前の第9号は8億2,500万ドル(2023年)。','https://www.felicis.com/blog/fund-x','高');
INSERT INTO vc_fund VALUES ('Accel','後期側(Leaders Fund V＋サイドカー)','50億ドル','5000.0','2026年4月14日','組成完了','非公開','同社の公式発表で合計50億ドルを確認。内訳は記載なし。','https://www.accel.com/news/ourlatestfundearlyinsightandenduringpartnership','高');
INSERT INTO vc_fund VALUES ('Accel','早期側(4本立て)','35億ドル','3500.0','2026年8月11日','組成完了','非公開','米国・欧州・イスラエル・インドの初期投資を支える4本。個別金額は発表になし。','https://www.accel.com/news/our-enduring-commitment-to-investing-at-the-earliest-stages','高');
INSERT INTO vc_fund VALUES ('Index Ventures','Index Ventures XII＋Growth VII','23億ドル','2300.0','2024年7月10日','組成完了','非公開','ベンチャー8億ドル、成長15億ドル。','https://www.indexventures.com/perspectives/relationships-that-reshape-industries-index-launches-23bn-in-new-funds/','高');
INSERT INTO vc_fund VALUES ('Lux Capital','Lux Ventures IX','15億ドル','1500.0','2026年1月7日','組成完了','非公開','同社の発表で15億ドル。運用総額70億ドル。(Muse調査: 産業革新投資機構JICが5,000万ドルを出資、JIC公式一覧が出典・未確認)','https://www.luxcapital.com/news/announcing-lux-ventures-ix','高');
INSERT INTO vc_fund VALUES ('Union Square Ventures','中心ファンド＋機会ファンド(2026年)','9億ドル','900.0','2026年10月8日','組成完了','非公開','同社の発表で9億ドル。前回の中心ファンドは2.75億ドル。内訳は発表になし。','https://www.usv.com/writing/the-next-chapter-of-usv','高');
INSERT INTO vc_fund VALUES ('Menlo Ventures','Menlo Ventures XVII＋Menlo Inflection IV','30億ドル','3000.0','2026年6月23日','組成完了','非公開','同社の発表で約30億ドル(同社最大)。XVIIはシード〜A、Inflection IVはB以降。個別金額は未公表。','https://menlovc.com/perspective/menlo-turns-50-and-announces-3b-in-fresh-capital-to-go-all-in-on-ai/','高');
INSERT INTO vc_fund VALUES ('Peak XV Partners','India Seed・India Venture・APACの3本','13億ドル','1300.0','2026年2月20日','組成完了','非公開','同社の発表で新たに合計13億ドルの出資約束。個別金額は未記載。','https://www.peakxv.com/announcement/three-new-funds-for-exceptional-founders-in-india-apac-and-beyond','高');
INSERT INTO vc_fund VALUES ('Initialized Capital','Fund VI(中心＋機会)','7億ドル','700.0','2021年12月14日','組成完了','非公開(機関・大学基金・財団という種類のみ)','中心5.3億・機会1.7億ドル。運用総額32億ドル超。','https://blog.initialized.com/2021/12/announcing-initialized-fund-vi/','高');
INSERT INTO lp_side VALUES ('CalPERS(米カリフォルニア州職員退職年金基金)','ベンチャー・ポートフォリオの純資産(NAV)が約76億ドル(2026年6月の事務局資料)。2026年は、ベンチャー・成長への配分を増やす方針。','https://calpers.ca.gov/documents/202606-invest-agenda-item06c-01-a/download?inline=');
INSERT INTO lp_side VALUES ('CalSTRS(米カリフォルニア州教職員退職年金基金)','2026年上半期に、PE・VC・プライベートクレジット・不動産で、合計90億ドル超の新規コミットを開示。','https://fundlinx.ai/resources/calstrs-commits-more-than-9-billion-to-private-markets-managers-in-the-first-half-of-2026');
INSERT INTO lp_side VALUES ('CalPERS(Lightspeedへの出資)','2020年に、Lightspeedの4本のファンドへ合計4億ドルをコミットと報道(当時のVC責任者ベン・リー氏の下)。のちにベンチャーの配分を約8億ドルから最大50億ドルへ拡大する方針。','https://pitchbook.com/news/articles/calpers-venture-asset-class-tiger-lightspeed');
INSERT INTO lp_side VALUES ('カリフォルニア大学基金(UC Investments)','Sequoiaの20本のファンドのLP。2018年以降8億ドル超を投じ、現金の分配は4,300万ドル、約半数が含み損と、公的記録の開示請求で報じられた(Business Insider)。','https://alphapartners.com/press/business-insider-half-of-sequoia-capitals-vc-funds-since-2018-have-posted-losses-for-the-university-of-californias-endowment/');
INSERT INTO lp_side VALUES ('ミシガン大学基金','Sequoia Capital U.S. Venture Fund XV(2015年組成)の30LPのうちの1つ(PitchBook)。Sequoiaが同基金の退出を求めたと、2020年にAxiosが報道。','https://pitchbook.com/profiles/fund/14823-10F');
INSERT INTO lp_side VALUES ('韓国 国民年金公団(NPS)','2026年7月、a16zやSequoiaなど、米国の有名VC6社と協力の覚書(MOU)を締結。具体的な出資額の約束ではありません。','https://www.kedglobal.com/nps-watch/newsView/ked202607260001');
INSERT INTO lp_side VALUES ('東京都(大学発スタートアップ等促進ファンド)','東京都が50億円を出資するファンド・オブ・ファンズ。出資先のファンド全体の出資約束額は800億円超(2025年12月発表)。','https://www.startupandglobalfinancialcity.metro.tokyo.lg.jp/documents/d/startupandglobalfinancialcity/university-deeptech-fund_5240');
